const char *layer_name_klaw(uint8_t layer, bool left) {
    static const char *const names[][2] = {{"ALPHA", "ALPHA"}, {"NUMBER", "NAVIGATE"}, {"CUT/PASTE", "CODE"}, {"FUNCT", "SYMBOL"}};
    return layer < ARRAY_SIZE(names) ? names[layer][left ? 0 : 1] : NULL;
}

